package tr.kasadenge.app;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.view.*;import android.widget.*;import android.graphics.*;import android.speech.tts.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
import com.google.mlkit.vision.common.InputImage;import com.google.mlkit.vision.text.TextRecognition;import com.google.mlkit.vision.text.latin.TextRecognizerOptions;
public final class MainActivity extends Activity {
 WebView web;FrameLayout root;CashDb db;TextToSpeech tts;boolean voiceReady;String csv="",photoToken="";static final int EXPORT=41,IMPORT=42,PHOTO=43,CSV=44;
 @Override public void onCreate(Bundle state){super.onCreate(state);android.content.pm.PackageInfo engine=WebView.getCurrentWebViewPackage();int engineVersion=0;try{if(engine!=null)engineVersion=Integer.parseInt(engine.versionName.split("\\.")[0]);}catch(Exception ignored){}if(engineVersion<80){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(36,80,36,36);TextView text=new TextView(this);text.setText(R.string.webview_update_message);text.setTextSize(18);box.addView(text);Button button=new Button(this);button.setText(R.string.webview_update_button);String enginePackage=engine==null?"com.google.android.webview":engine.packageName;button.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("market://details?id="+enginePackage)));}catch(Exception e){Toast.makeText(this,"Uygulama mağazasından Android System WebView / Chrome'u güncelleyin.",Toast.LENGTH_LONG).show();}});box.addView(button);setContentView(box);return;}db=new CashDb(this);root=new FrameLayout(this);web=new WebView(this);root.addView(web);setContentView(root);
  root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());if(Build.VERSION.SDK_INT>=30)keyboardVisibility(insets.isVisible(WindowInsets.Type.ime()));return insets;});
  root.getViewTreeObserver().addOnGlobalLayoutListener(()->{if(Build.VERSION.SDK_INT<30){android.graphics.Rect visible=new android.graphics.Rect();root.getWindowVisibleDisplayFrame(visible);keyboardVisibility(root.getRootView().getHeight()-visible.bottom>120*getResources().getDisplayMetrics().density);}});
  WebSettings w=web.getSettings();w.setJavaScriptEnabled(true);w.setDomStorageEnabled(false);w.setAllowFileAccess(false);w.setAllowContentAccess(false);w.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);w.setCacheMode(WebSettings.LOAD_NO_CACHE);web.addJavascriptInterface(new Bridge(),"KasaDenge");
  web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest request){Uri u=request.getUrl();if(!"appassets.androidplatform.net".equals(u.getHost()))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));try{String p=u.getPath();if(p==null||p.equals("/"))p="/index.html";if(!p.matches("/[a-zA-Z0-9._-]+"))throw new IOException();String mime=(p.endsWith(".js")||p.endsWith(".mjs"))?"application/javascript":p.endsWith(".css")?"text/css":p.endsWith(".ttf")?"font/ttf":p.endsWith(".svg")?"image/svg+xml":"text/html";WebResourceResponse r=new WebResourceResponse(mime,"UTF-8",getAssets().open(p.substring(1)));java.util.Map<String,String> headers=new java.util.HashMap<>();headers.put("Content-Security-Policy","default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'none'; object-src 'none'; base-uri 'none'");r.setResponseHeaders(headers);return r;}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",null,new ByteArrayInputStream(new byte[0]));}}
   @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !"appassets.androidplatform.net".equals(r.getUrl().getHost());}});
  web.loadUrl("https://appassets.androidplatform.net/index.html");colors();tts=new TextToSpeech(this,status->{if(status==TextToSpeech.SUCCESS){for(Voice v:tts.getVoices()==null?Collections.<Voice>emptySet():tts.getVoices())if(v.getLocale().getLanguage().equals("tr")&&!v.isNetworkConnectionRequired()){tts.setVoice(v);voiceReady=true;break;}}});
 }

 @Override protected void onResume(){super.onResume();refresh();}
 boolean keyboardOpen=false;
 void keyboardVisibility(boolean visible){if(keyboardOpen==visible)return;keyboardOpen=visible;web.post(()->web.evaluateJavascript("window.dispatchEvent(new CustomEvent('keyboard-visibility',{detail:{visible:"+visible+"}}))",null));}
 void refresh(){if(web!=null)web.post(()->web.evaluateJavascript("window.dispatchEvent(new Event('native-refresh'))",null));}
 void message(String text){runOnUiThread(()->{Toast.makeText(this,text,Toast.LENGTH_LONG).show();refresh();});}
 void colors(){if(web==null)return;try{String theme=db.settings().optString("theme","system");boolean dark=theme.equals("dark")||theme.equals("system")&&(getResources().getConfiguration().uiMode&48)==32;int bg=Color.parseColor(dark?"#0D1524":"#F3F6FB");root.setBackgroundColor(bg);web.setBackgroundColor(bg);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(Build.VERSION.SDK_INT<27?Color.parseColor("#173F3B"):bg);getWindow().getDecorView().setSystemUiVisibility(dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);}catch(Exception ignored){}}
 interface Work{Object run()throws Exception;}
 String reply(Work work){try{return new JSONObject().put("ok",true).put("data",work.run()).toString();}catch(Exception e){try{return new JSONObject().put("ok",false).put("error",e.getMessage()==null?"İşlem tamamlanamadı.":e.getMessage()).toString();}catch(Exception ignored){return "{\"ok\":false,\"error\":\"İşlem tamamlanamadı\"}";}}}
 public final class Bridge{
 @JavascriptInterface public void pickDate(String value,String max,String token){runOnUiThread(()->{try{java.time.LocalDate initial;try{initial=java.time.LocalDate.parse(value);}catch(Exception e){initial=java.time.LocalDate.now();}DatePickerDialog picker=new DatePickerDialog(MainActivity.this,(view,y,m,d)->{try{JSONObject result=new JSONObject().put("token",token).put("date",java.time.LocalDate.of(y,m+1,d).toString());web.evaluateJavascript("window.dateResult("+result.toString()+")",null);}catch(Exception ignored){}},initial.getYear(),initial.getMonthValue()-1,initial.getDayOfMonth());if(!max.isEmpty()){java.time.LocalDate limit=java.time.LocalDate.parse(max);picker.getDatePicker().setMaxDate(limit.atTime(23,59,59).atZone(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli());}picker.show();}catch(Exception e){Toast.makeText(MainActivity.this,"Tarih seçimi açılamadı.",Toast.LENGTH_LONG).show();}});}

 @JavascriptInterface public String state(){return reply(()->db.state().put("systemDark",(getResources().getConfiguration().uiMode&48)==32));}
 @JavascriptInterface public String settings(String raw){return reply(()->{db.saveConfig(raw);runOnUiThread(()->colors());return true;});}
 @JavascriptInterface public String draft(String raw){return reply(()->{db.draft(raw);return true;});}
 @JavascriptInterface public String savePosTotal(String raw){return reply(()->db.savePosTotal(raw));}
 @JavascriptInterface public String receivePos(String raw){return reply(()->db.receivePos(raw));}
 @JavascriptInterface public String savePos(String raw){return reply(()->db.savePos(raw));}
 @JavascriptInterface public String deleteCounts(String raw){return reply(()->db.deleteCounts(raw));}
 @JavascriptInterface public String closeCount(String raw){return reply(()->db.closeCount(raw));}
 @JavascriptInterface public void speak(String text){runOnUiThread(()->{if(!voiceReady||tts==null){message("Çevrimdışı Türkçe ses bulunamadı. Telefonun metin okuma ayarlarından Türkçe ses yükleyin.");return;}tts.speak(text.substring(0,Math.min(500,text.length())),TextToSpeech.QUEUE_FLUSH,null,"cash-result");});}
 @JavascriptInterface public void photo(String token){if(token==null||!token.matches("[a-zA-Z0-9_-]{1,80}"))return;photoToken=token;runOnUiThread(()->choose(PHOTO,"image/*",null));}
 @JavascriptInterface public void exportData(){runOnUiThread(()->choose(EXPORT,"application/json","İşletme Kasa-Yedek-"+java.time.LocalDate.now()+".json"));}
 @JavascriptInterface public void csv(String content){if(content.length()>8000000){message("Rapor çok büyük; tarih aralığını daraltın.");return;}csv=content;runOnUiThread(()->choose(CSV,"text/csv","İşletme Kasa-Rapor-"+java.time.LocalDate.now()+".csv"));}
 @JavascriptInterface public void print(){runOnUiThread(()->{android.print.PrintManager manager=(android.print.PrintManager)getSystemService(PRINT_SERVICE);manager.print("İşletme Kasa raporu",web.createPrintDocumentAdapter("İşletme Kasa"),null);});}
 @JavascriptInterface public void importData(){runOnUiThread(()->new AlertDialog.Builder(MainActivity.this).setTitle("Yedekten Ekle").setMessage("Mevcut kapanışlar korunur; aynı kasa/tarih kapanışları üzerine yazılmaz. Yedekteki taslak ve eski revizyonlar dosyada kalır; güncel kapanışlar ve yeni kasalar eklenir.").setNegativeButton("Vazgeç",null).setPositiveButton("Dosya Seç",(d,w)->choose(IMPORT,"*/*",null)).show());}
 }
 void choose(int code,String type,String name){try{Intent i=new Intent(name==null?Intent.ACTION_OPEN_DOCUMENT:Intent.ACTION_CREATE_DOCUMENT).setType(type).addCategory(Intent.CATEGORY_OPENABLE);if(name!=null)i.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,code);}catch(Exception e){message("Dosya seçici açılamadı.");}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(req==PHOTO){readPhoto(uri);return;}new Thread(()->{try{if(req==EXPORT||req==CSV){String text=req==EXPORT?db.state().toString(2):"\ufeff"+csv;try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Dosya yazılamadı.");out.write(text.getBytes(StandardCharsets.UTF_8));}message("Dosya kaydedildi.");}else if(req==IMPORT){String text;try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException("Dosya okunamadı.");byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){out.write(buffer,0,n);if(out.size()>16000000)throw new IOException("Yedek en fazla 16 MB olabilir.");}text=out.toString("UTF-8");}message(db.merge(text));}}catch(Exception e){message("Dosya işlemi tamamlanamadı: "+e.getMessage());}},"cash-files").start();}
 void readPhoto(Uri uri){final String token=photoToken;message("Fotoğraf cihaz üzerinde okunuyor…");new Thread(()->{try{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,o);}if(o.outWidth<1||o.outHeight<1)throw new IOException("Görsel okunamadı.");o.inSampleSize=1;while(Math.max(o.outWidth/o.inSampleSize,o.outHeight/o.inSampleSize)>2400)o.inSampleSize*=2;o.inJustDecodeBounds=false;Bitmap bitmap;try(InputStream in=getContentResolver().openInputStream(uri)){bitmap=BitmapFactory.decodeStream(in,null,o);}if(bitmap==null)throw new IOException("Görsel açılamadı.");int orientation=1;try(InputStream ex=getContentResolver().openInputStream(uri)){orientation=new android.media.ExifInterface(ex).getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION,1);}catch(Exception ignored){}Matrix matrix=new Matrix();switch(orientation){case 2:matrix.setScale(-1,1);break;case 3:matrix.setRotate(180);break;case 4:matrix.setScale(1,-1);break;case 5:matrix.setRotate(90);matrix.postScale(-1,1);break;case 6:matrix.setRotate(90);break;case 7:matrix.setRotate(270);matrix.postScale(-1,1);break;case 8:matrix.setRotate(270);break;}if(orientation!=1){Bitmap fixed=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),matrix,true);if(fixed!=bitmap){bitmap.recycle();bitmap=fixed;}}final Bitmap imageBitmap=bitmap;ByteArrayOutputStream preview=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,75,preview);String image="data:image/jpeg;base64,"+android.util.Base64.encodeToString(preview.toByteArray(),android.util.Base64.NO_WRAP);com.google.mlkit.vision.text.TextRecognizer recognizer=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);recognizer.process(InputImage.fromBitmap(imageBitmap,0)).addOnSuccessListener(result->{if(!token.startsWith("pos_")&&CashbookOcr.isTemplate(result))new Thread(()->CashbookOcr.fields(imageBitmap,result,recognizer,fields->showPhoto(result,fields,image,token,imageBitmap,recognizer)),"cashbook-fields").start();else showPhoto(result,new JSONObject(),image,token,imageBitmap,recognizer);}).addOnFailureListener(e->{imageBitmap.recycle();recognizer.close();message("Fotoğraf okunamadı; daha net veya düzgün yönlü bir fotoğraf deneyin.");});}catch(Exception e){message("Fotoğraf açılamadı: "+e.getMessage());}},"cash-ocr").start();}
 @Override public void onBackPressed(){if(web==null){super.onBackPressed();return;}web.evaluateJavascript("window.handleBack && window.handleBack()",v->{if(!"true".equals(v))moveTaskToBack(true);});}
 @Override protected void onDestroy(){if(tts!=null){tts.stop();tts.shutdown();}if(web!=null){web.removeJavascriptInterface("KasaDenge");web.destroy();web=null;}if(db!=null)db.close();super.onDestroy();}
 void showPhoto(com.google.mlkit.vision.text.Text result,JSONObject fields,String image,String token,Bitmap bitmap,com.google.mlkit.vision.text.TextRecognizer recognizer){try{JSONObject obj=new JSONObject().put("text",token.startsWith("pos_")?ReceiptOcr.orderedText(result):result.getText()).put("rawText",result.getText()).put("orderedText",CashbookOcr.isTemplate(result)?ReceiptOcr.orderedText(result,.9):ReceiptOcr.orderedText(result)).put("bookFields",fields).put("image",image).put("token",token);if(web!=null)web.post(()->{if(web!=null)web.evaluateJavascript("window.photoResult && window.photoResult("+obj.toString()+")",null);});}catch(Exception e){message("Okuma Sonucu Gösterilemedi.");}finally{bitmap.recycle();recognizer.close();}}
}
